import{services as originalServices}from'./content.js?v=c0009ba8a4';
import{services as design42Services}from'./services-04-2.js?v=c0009ba8a4';
import{initExpandingSearch}from'./expanding-search.js?v=c0009ba8a4';
import{initFaqSection}from'./faq-section.js?v=c0009ba8a4';
import{initFrostNav}from'./frost-nav.js?v=c0009ba8a4';
import{initFolderFloat}from'./folder-float.js?v=c0009ba8a4';
const services=['04.2','04.5'].includes(document.documentElement.dataset.design)?design42Services:originalServices;
// Set by build.mjs on 04.5 only: the patient portal's base URL (PORTAL_URL).
const portal=document.documentElement.dataset.portal;
const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
if(document.documentElement.dataset.design==='04.2')initFrostNav(document.querySelector('.topbar'));
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
if(!reduced){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting){target.classList.add('in-view');observer.unobserve(target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const toggle=document.querySelector('.menu-toggle'),panel=document.querySelector('.menu-panel'),backdrop=document.querySelector('.menu-backdrop');
function closeMenu(restore=false){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu');panel.hidden=true;backdrop.hidden=true;if(restore)toggle.focus()}
function openMenu(){toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','Close menu');panel.hidden=false;backdrop.hidden=false}
toggle.setAttribute('aria-label','Open menu');toggle.addEventListener('click',()=>panel.hidden?openMenu():closeMenu());backdrop.addEventListener('click',()=>closeMenu(true));panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{closeMenu();const el=a.hash?document.querySelector(a.hash):null;if(el){el.setAttribute('tabindex','-1');el.focus({preventScroll:true})}}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)closeMenu(true)});
// Gentle photographic drift and layered sticky cards, driven by scroll position.
if(!reduced){const hero=document.querySelector('.hero'),photo=document.querySelector('.hero-photo'),cards=[...document.querySelectorAll('.treatment-card,.visit-card')];let pending=false;function paint(){pending=false;const y=scrollY;if(y<hero.offsetHeight&&!photo.closest('[data-glass]'))photo.style.translate=`0 ${y*.12}px`;cards.forEach(card=>{const r=card.getBoundingClientRect(),next=card.nextElementSibling;if(!next)return;const n=next.getBoundingClientRect(),progress=Math.max(0,Math.min(1,(r.bottom-n.top+80)/Math.max(1,r.height)));card.style.transform=`scale(${1-progress*.035})`;card.style.filter=`brightness(${1-progress*.12})`})}function request(){if(!pending){pending=true;requestAnimationFrame(paint)}}addEventListener('scroll',request,{passive:true});addEventListener('resize',request,{passive:true});paint()}
const dialog=document.querySelector('#care-dialog'),content=document.querySelector('#dialog-content');let opener;
function show(html,trigger){opener=trigger;content.innerHTML=html;closeMenu();dialog.showModal();document.body.style.overflow='hidden';dialog.scrollTop=0;dialog.querySelector('.dialog-close').focus();
 // Content rises in a little after the panel, row by row, so a swap inside an open popup reads as a change, not a jump.
 if(!reduced)[...content.children].flatMap(el=>el.matches('.all-care-list,.dialog-list,.care-folders')?[...el.children]:[el]).slice(0,14).forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'none'}],{duration:480,delay:60+i*35,easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'}))}
// 04.5 (with a portal): choosing a service (search, all care, a folder) opens its booking straight away; the previews keep the details popup.
function showService(id,trigger){const s=services.find(s=>s.id===id);if(!s)return;if(portal){location.assign(`${portal}/book?service=${encodeURIComponent(s.id)}`);return}show(`<p class="mono">Care that fits your life</p><h2 id="dialog-title">${esc(s.name)}</h2><p>${esc(s.description)}</p><div class="dialog-price"><strong>From €${s.price}</strong><span>${s.duration} · video consultation</span></div><ul class="dialog-list">${s.topics.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="dialog-note">Example prices are confirmed per country before launch. Prescriptions, certificates, referrals, and tests depend on your clinician’s assessment. Not an emergency service. In an emergency, call 112.</p>${portal?`<a class="button dark" href="${esc(portal)}/book?service=${encodeURIComponent(s.id)}">Book ${esc(s.name)}</a>`:'<a class="button dark" href="https://carevia.triple-labs-8416.chatgpt.site/#services" target="_blank" rel="noopener">Explore on Carevia</a>'}`,trigger)}
const searchRoot=document.querySelector('[data-care-search]');
if(searchRoot)initExpandingSearch(searchRoot,services,(service,trigger)=>showService(service.id,trigger),()=>closeMenu());
const faqRoot=document.querySelector('[data-faq-section]');
if(faqRoot)initFaqSection(faqRoot);
document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>showService(b.dataset.service,b)));
// The whole treatment card opens its details, as if Details was clicked (so focus returns to that button when the dialog closes).
// Clicks on the card's own buttons or links keep their action, and selecting text in the card doesn't open it.
document.querySelectorAll('.treatment-card').forEach(card=>{const open=card.querySelector('.care-open');if(open)card.addEventListener('click',e=>{if(!e.target.closest('a,button')&&!getSelection().toString())open.click()})});
document.querySelectorAll('[data-all-care]').forEach(b=>b.addEventListener('click',e=>{show(`<p class="mono">Seven areas of care</p><h2 id="dialog-title">Find your starting point.</h2><p>Choose an area to explore the consultation, example price, and next steps.</p>${services[0].categories?careFolders():`<div class="all-care-list">${services.map(s=>`<button data-service="${s.id}">${esc(s.name)}<span>From €${s.price}</span></button>`).join('')}</div>`}`,e.currentTarget);const folders=content.querySelector('.care-folders');if(folders)initFolderFloat(folders,{onSelect:(pill,folder)=>showService(folder.dataset.service,opener)});else content.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>showService(b.dataset.service,opener)))}));
// 04.2/04.5: every area is a folder; opening it floats that area's services out (scripts/folder-float.js). Any service opens its area's details.
function careFolders(){return`<div class="care-folders">${services.map(s=>{const n=s.categories.length,sub=`${n} service${n===1?'':'s'} · From €${s.price}`;return`<div class="folder-float" data-service="${s.id}" style="--ff-n:${n}"><div class="folder-float__folder"><span class="folder-float__back" aria-hidden="true"></span><span class="folder-float__paper" aria-hidden="true"></span><span class="folder-float__front" aria-hidden="true"><span class="folder-float__label">${esc(s.name)}</span><span class="folder-float__sub">${sub}</span></span><button type="button" class="folder-float__trigger" aria-expanded="false" aria-label="${esc(s.name)}, ${sub}"></button></div><div class="folder-float__items">${s.categories.map((c,i)=>`<button type="button" class="folder-float__item" tabindex="-1" style="--i:${i}"><span class="folder-float__drift">${esc(c)}</span></button>`).join('')}</div></div>`}).join('')}</div>`}dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus({preventScroll:true})});
document.querySelectorAll('.faq-toggle').forEach(b=>b.addEventListener('click',()=>{const item=b.closest('.faq-item'),open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));item.classList.toggle('open',!open);item.querySelector('.faq-answer').inert=open}));
const statements={heard:['Good care starts with being heard. A little more understanding. A little more clarity. More room to be you.','A conversation with space for your questions, your concerns, and what matters most to you.'],clear:['A real conversation. A clear price. A next step you understand. Care should feel more straightforward.','See the consultation price before confirming. Pay for the visit you choose, with no subscription.'],together:['The conversation is just the beginning. Keep the details together, and your next step close.','Your clinical summary, and anything your doctor decides to issue, is available through iMED.']};document.querySelectorAll('[data-principle]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-principle]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b))});const [heading,copy]=statements[b.dataset.principle],h=document.querySelector('.approach-statement');h.textContent=heading;document.querySelector('.principle-copy').textContent=copy;if(!reduced){const rise=[{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}];h.animate(rise,{duration:450,easing:'cubic-bezier(.22,1,.36,1)'});document.querySelector('.principle-copy').animate(rise,{duration:450,delay:70,easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'})}}));
import{GlassPhoto}from'./glass.js?v=c0009ba8a4';document.querySelectorAll('.hero [data-glass],.wide-banner [data-glass],.treatment-card [data-glass],.start-card [data-glass]').forEach(el=>new GlassPhoto(el,reduced));

// Load the Paper heatmap only when its card nears the viewport; the static logo stays if WebGL is unavailable.
const heatmap=document.querySelector('[data-heatmap]');
if(heatmap&&'IntersectionObserver'in window)new IntersectionObserver(([entry],observer)=>{if(!entry.isIntersecting)return;observer.disconnect();import('./start-heatmap.js?v=c0009ba8a4').then(m=>m.mountHeatmap(heatmap)).catch(()=>{})},{rootMargin:'400px'}).observe(heatmap);
